  try { return JSON.parse(texto); } catch (e) { return { error: 'No se pudo leer la respuesta de Claude', texto }; }
}
const hoy = new Date().toISOString().slice(0, 10);
// Google Sheets acepta hasta 50.000 caracteres por celda.
const celda = s => (s && s.length > 45000 ? s.slice(0, 45000) + ' [cortado]' : s);
// Junta los mensajes por conversación. Deja las que no tienen mensajes nuevos hace 30 minutos
// y que el administrador todavía no revisó (o que siguieron después de revisarlas).
const filas = n => $(n).all().map(i => i.json).filter(o => o.sesion);
const revisados = {};
for (const c of filas('Leer casos')) revisados[c.sesion] = Math.max(revisados[c.sesion] || 0, Number(c.mensajes_revisados) || 0);
const clientes = $('Leer clientes').all().map(i => i.json.nombre).filter(Boolean);
const hace30 = Date.now() - 30 * 60 * 1000;
const conversaciones = [];
for (const [chatbot, hoja] of [['leads', 'Leer leads'], ['soporte', 'Leer soporte']]) {
  const porSesion = {};
  for (const m of filas(hoja)) (porSesion[m.sesion] ??= []).push(m);
  for (const [sesion, mensajes] of Object.entries(porSesion)) {
    if (Date.parse(mensajes[mensajes.length - 1].fecha) > hace30) continue;
    if (mensajes.length <= (revisados[sesion] || 0)) continue;
    conversaciones.push({ chatbot, sesion, mensajes, clientes });
  }
}
return conversaciones.slice(0, $('Config').first().json.max_conversaciones).map(json => ({ json }));

